<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableUidAttributeHolder;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableCodeAttributeHolder;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableTenantAttributeHolder;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableTypeAttributeHolder;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableValueAttributeHolder;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableEnabledAttributeHolder;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder\TemplateVariableVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class TemplateVariableAttributes
{
    use TemplateVariableUidAttributeHolder;
    use TemplateVariableCodeAttributeHolder;
    use TemplateVariableTenantAttributeHolder;
    use TemplateVariableTypeAttributeHolder;
    use TemplateVariableValueAttributeHolder;
    use TemplateVariableEnabledAttributeHolder;
    use TemplateVariableVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'code' => 'unsetCode',
      'tenant' => 'unsetTenant',
      'type' => 'unsetType',
      'value' => 'unsetValue',
      'enabled' => 'unsetEnabled',
      'version' => 'unsetVersion',
    ];

    public function createNewInstance(): TemplateVariable
    {
        $errors = new ConstraintFailList();
        $uid = $this->uidTryBuildInitial($errors);
        $code = $this->codeTryBuildInitial($errors);
        $tenant = $this->tenantTryBuildInitial($errors);
        $type = $this->typeTryBuildInitial($errors);
        $value = $this->valueTryBuildInitial($errors);
        $enabled = $this->enabledTryBuildInitial($errors);
        $version = $this->versionTryBuildInitial($errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($code !== null);
        \assert($tenant !== null);
        \assert($type !== null);
        return new TemplateVariable(
            uid: $uid,
            code: $code,
            tenant: $tenant,
            type: $type,
            value: $value,
            enabled: $enabled,
            version: $version,
        );
    }
    public function withAssertedRules(): TemplateVariableAttributes
    {
        $value = new TemplateVariableAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedCodeRules($value, $errorsList);
        $this->withAssertedTenantRules($value, $errorsList);
        $this->withAssertedTypeRules($value, $errorsList);
        $this->withAssertedValueRules($value, $errorsList);
        $this->withAssertedEnabledRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): TemplateVariableAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultCode();
        $this->withDefaultTenant();
        $this->withDefaultType();
        $this->withDefaultValue();
        $this->withDefaultEnabled();
        $this->withDefaultVersion();
        return $this;
    }
}
